# Surah Al-Baqarah (chapter 2) — part 9: ayat 81-90 (IDs 88-97)
SURAH = 2

ENTRIES = {
88: (
"ہاں! جس نے برائی کا کام کیا اور اس کے (بُرے) عمل نے اس کو گھیر لیا تو یہی جہنم والے ہیں — وہ اس میں ہمیشہ رہیں گے۔",
"""۱۔ ’’بَلٰی‘‘ — ہاں، (دعویٰ کے برخلاف) بات یہ ہے — گنتی کے چند دنوں والی خوش فہمی غلط ہے؛ اصل حقیقت یہ ہے۔
۲۔ ’’مَنْ كَسَبَ سَيِّئَةً‘‘ — جس نے برائی کا کام کیا — یعنی جان بوجھ کر گناہ کیا۔
۳۔ ’’وَأَحَاطَتْ بِهِ خَطِيئَتُهُ‘‘ — اور اس کی خطا (گناہ) نے اسے گھیر لیا — یعنی گناہ اس کے دل اور عمل پر ایسا چھا گیا کہ اس سے نکالنے کا راستہ ہی نہ بچا۔
۴۔ ’’فَأُولَٰئِكَ أَصْحَابُ النَّارِ‘‘ — تو یہی جہنم والے ہیں — وہ اس میں ہمیشہ رہیں گے۔ یعنی جو گناہوں میں ڈوب کر توبہ نہ کرے اسے ابدی سزا ملتی ہے۔
۵۔ یہاں ’’گھیر لیا‘‘ کی تعبیر پر غور کریں — ایک گناہ دوسرے گناہ کو، وہ تیسرے کو جنم دیتا ہے — اس دوران ایمان کمزور ہوتا جاتا ہے۔ یہی تباہی کا عملی طریقہ ہے۔
۶۔ عملی سبق: چھوٹی لغزش کو فوراً توبہ اور استغفار سے مٹائیں — ورنہ وہ آہستہ آہستہ آپ کو گھیر لے گی۔"""
),
89: (
"اور جو لوگ ایمان لائے اور نیک عمل کیے — یہی جنت والے ہیں — وہ اس میں ہمیشہ رہیں گے۔",
"""۱۔ پچھلی آیت جہنم والے کی وعید تھی؛ اب جنت والے کی بشارت ہے — ایمان اور نیک عمل دونوں درکار ہیں۔
۲۔ ’’آمَنُوا وَعَمِلُوا الصَّالِحَاتِ‘‘ — ایمان لائے اور نیک اعمال کیے — ایمان خالی دعویٰ نہیں بلکہ عمل کی شکل بن کر سامنے آتا ہے۔
۳۔ ’’أُولَٰئِكَ أَصْحَابُ الْجَنَّۃِ‘‘ — یہی جنت والے ہیں — دائمی جاودانی — یعنی ابدی مسرت اور اللہ کی خوشنودی۔
۴۔ یہاں توازنِ فرقہ واضح ہے: نہ محض ایمان پر فخر اور نہ محض اعمال کی ریکارڈنگ — دونوں کا مل بیٹھنا ہی جنت تک کا راستہ ہے۔
۵۔ عملی سبق: زندگی میں اپنے ایمان اور اعمال کا روزانہ محاسبہ کریں — چھوٹی نیکیاں بھی جنت کی سیڑھیاں بناتی ہیں۔"""
),
90: (
"اور (یاد کرو) جب ہم نے بنی اسرائیل سے پکا عہد لیا کہ اللہ کے سوا کسی کی عبادت نہ کرو، ماں باپ کے ساتھ بھلائی کرو، رشتہ داروں اور یتیموں اور مسکینوں کے ساتھ (بھلائی کرو)، اور لوگوں سے اچھی بات کہو، اور نماز قائم کرو اور زکوٰۃ دو — پھر تم سب پھر گئے سوائے تم میں سے تھوڑوں کے اور تم منہ موڑنے والے ہو۔",
"""۱۔ اللہ بنی اسرائیل سے لیے گئے جامع عہد کی تفصیل بیان فرماتا ہے — پانچ بڑے ارکان: توحید، والدین سے حسن سلوک، رشتہ داروں و یتیموں و مسکینوں کے ساتھ بھلائی، لوگوں سے اچھی گفتگو، نماز و زکوٰۃ۔
۲۔ ’’لَا تَعْبُدُونَ إِلَّا اللّٰہَ‘‘ — اللہ کے سوا کسی کی عبادت نہ کرو — عبادت صرف اللہ کی؛ شرک سے پاک۔
۳۔ ’’وَبِالْوَالِدَيْنِ إِحْسَانًا‘‘ — والدین کے ساتھ بھلائی — یعنی احسانِ تربیتی کا بدلہ اطاعت اور محبت سے ادا کرنا۔
۴۔ ’’وَذِي الْقُرْبَىٰ وَالْيَتَامَىٰ وَالْمَسَاكِينِ‘‘ — رشتہ دار، یتیم اور مسکین — یعنی معاشرہ کے کمزور طبقے؛ ان کے حقوق مسلمان کی ذمہ داری ہیں۔
۵۔ ’’وَقُولُوا لِلنَّاسِ حُسْنًا‘‘ — لوگوں سے اچھی بات کہو — زبان کی تہذیب اور اظہار کا ادب — یہ سماجی اچھے تعلقات کی بنیاد ہے۔
۶۔ ’’وَأَقِيمُوا الصَّلَاةَ وَآتُوا الزَّكَاةَ‘‘ — نماز اور زکوٰۃ قائم کرو — حقوق اللہ اور حقوق الناس دونوں۔
۷۔ ’’ثُمَّ تَوَلَّيْتُمْ إِلَّا قَلِيلًا مِّنكُمْ وَأَنتُم مُّعْرِضُونَ‘‘ — پھر تم سب پھر گئے سوائے تھوڑوں — یعنی بعد میں انہوں نے یہ عہد توڑ دیا۔
۸۔ عملی سبق: یہ پانچ ارکان ہر مسلمان کی بھی بنیادی ذمہ داریاں ہیں — توحید، والدین، کمزوروں، اچھی گفتگو، نماز و زکوٰۃ۔"""
),
91: (
"اور (یاد کرو) جب ہم نے تم سے پکا عہد لیا کہ اپنے خون نہ بہاو اور اپنے آپ کو اپنے گھروں سے نہ نکالو — پھر تم نے عہد کیا اور تم اس پر گواہ ہو۔",
"""۱۔ بنی اسرائیل سے ایک اور خاص عہد: آپس میں لڑائیاں اور اخراج نہ کریں — یعنی داخلی امن و امان کی ضمانت۔
۲۔ ’’لَا تَسْفِكُونَ دِمَاءَكُمْ‘‘ — اپنے خون نہ بہاو — یعنی آپس میں ایک دوسرے کا قتل نہ کرو؛ قبائلی جنگ سے باز رہو۔
۳۔ ’’وَلَا تُخْرِجُونَ أَنفُسَكُم مِّن دِيَارِكُمْ‘‘ — اور اپنے لوگوں کو ان کے گھروں سے نہ نکالو — یعنی اخراج/بے گھری نہ کرو۔
۴۔ ’’ثُمَّ أَقْرَرْتُمْ وَأَنتُمْ تَشْهَدُونَ‘‘ — پھر تم نے عہد کیا اور تم اس پر گواہ ہو — یعنی یہ عہد تمہاری اپنی مرضی اور گواہی سے طے ہوا تھا۔
۵۔ بنی اسرائیل نے مدینے میں رہ کر یہ عہد توڑ دیا — آپس کی جنگیں اور اخراج دوبارہ شروع ہو گئے (جیسا کہ اگلی آیات میں بیان ہوگا)۔
۶۔ عملی سبق: مسلمانوں کے درمیان خانہ جنگی اور اخراجِ مسلمین سب سے سنگین گناہوں میں سے ہے — ہر صورت پر صلح اور اتحاد کو ترجیح دیں۔"""
),
92: (
"پھر تم وہی ہو جو ایک دوسرے کو قتل کرتے ہو اور اپنے میں سے ایک گروہ کو اس کے گھروں سے نکالتے ہو — ان کے خلاف گناہ اور زیادتی میں ایک دوسرے کی مدد کرتے ہو — اور اگر وہ قید ہو کر آئیں تو تم ان کا فدیہ لیتے ہو — حالانکہ ان کا اخراج ہی تم پر حرام ہے — کیا تم کتاب کے کچھ حصہ پر ایمان رکھتے ہو اور کچھ سے انکار کرتے ہو؟ پس اس کا بدلہ جو تم میں سے ایسا کرے وہ دنیاوی رسوائی کے سوا کچھ نہیں — اور قیامت کے دن وہ شدید ترین عذاب کی طرف لوٹائے جائیں گے — اور اللہ اس سے بے خبر نہیں جو تم عمل کرتے ہو۔",
"""۱۔ بنی اسرائیل کے منافقانہ رویے کی تفصیل بیان ہوئی: انہوں نے عہد توڑ کر آپس میں قتل اور اخراج شروع کر دیا — مگر قید ہو کر آنے والے کو فدیہ دے کر چھڑا لیتے تھے — یعنی ایک ہی عمل کو دوراہا لیتے تھے۔
۲۔ ’’تَظَاهَرُونَ عَلَيْهِم بِالْإِثْمِ وَالْعُدْوَانِ‘‘ — ان (مدینے کے دوسرے قبیلوں) کے خلاف گناہ اور زیادتی میں ایک دوسرے کی مدد کرتے ہو — یعنی بیرونی دشمن کے ساتھ مل کر اپنے ہی بھائی کے خلاف فوج کشی۔
۳۔ ’’وَإِن يَأْتُوكُمْ أُسَارَىٰ تُفَادُوهُمْ وَهُوَ مُحَرَّمٌ عَلَيْكُمْ إِخْرَاجُهُمْ‘‘ — اور اگر وہ قید ہو کر آئیں تو تم ان کا فدیہ دے کر چھڑا لیتے ہو — حالانکہ ان کا اخراج ہی تم پر حرام تھا۔ یعنی وہ حرام کو حلال سمجھ کر کرتے تھے اور فدیہ دے کر خود کو صاف جانتے تھے۔
۴۔ ’’أَفَتُؤْمِنُونَ بِبَعْضِ الْكِتَابِ وَتَكْفُرُونَ بِبَعْضٍ‘‘ — کیا تم کتاب کے ایک حصے پر ایمان رکھتے ہو اور دوسرے سے انکار کرتے ہو — یعنی منتخب دین اختیار کرنا۔
۵۔ ’’فَمَا جَزَاءُ مَن يَفْعَلُ ذَٰلِكَ… إِلَّا خِزْيٌ فِي الْحَيَاةِ الدُّنْيَا‘‘ — اس کا انجام دنیاوی رسوائی کے سوا کچھ نہیں — یعنی یہ منافقانہ دوغلا پن دنیا میں بھی ذلت کا سبب ہے۔
۶۔ ’’وَيَوْمَ الْقِيَامَةِ يُرَدُّونَ إِلَىٰ أَشَدِّ الْعَذَابِ‘‘ — اور قیامت کے دن شدید ترین عذاب کی طرف لوٹائے جائیں گے۔
۷۔ عملی سبق: دین کو منتخب نہ بنائیں؛ حرام کو حلال سمجھنے کی روش آخرت میں بھی مہنگی پڑتی ہے۔"""
),
93: (
"یہی وہ لوگ ہیں جنہوں نے آخرت کے بدلے دنیا کی زندگی خرید لی — تو نہ ان سے عذاب ہلکا کیا جائے گا اور نہ ان کی مدد کی جائے گی۔",
"""۱۔ بنی اسرائیل (اور ان جیسے) کی اصل بیماری کا علاج بیان ہوا: انہوں نے آخرت کو چھوڑ کر دنیا خرید لی۔
۲۔ ’’اشْتَرَوُا الْحَيَاةَ الدُّنْيَا بِالْآخِرَۃِ‘‘ — آخرت دے کر دنیا خریدی — یعنی دنیا کو ترجیح، آخرت کی پروا نہیں۔
۳۔ ’’فَلَا يُخَفَّفُ عَنْهُمُ الْعَذَابُ وَلَا هُمْ يُنصَرُونَ‘‘ — نہ ان سے عذاب ہلکا کیا جائے گا اور نہ ان کی مدد کی جائے گی — یعنی آخرت میں کوئی راحت اور کوئی مددگار نہیں۔
۴۔ دنیا کی محبت اصل بیماری ہے؛ جو دنیا کے لیے آخرت بیچے اس کے لیے ذاتِ نبوی کا سودا بھی ان کی مثال ہے۔
۵۔ عملی سبق: دنیاوی فائدہ ہر قیمت پر نہ لیں؛ دنیا درمیانی ہے — آخرت سب سے بڑی ہے۔"""
),
94: (
"اور بے شک ہم نے موسیٰ کو کتاب دی اور ان کے بعد پیغمبر بھیجتے رہے اور ہم نے عیسیٰ ابن مریم کو واضح نشانیاں دیں اور انہیں روح القدس سے مضبوط کیا — تو کیا جب کبھی تمہارے پاس کوئی پیغمبر وہ لے کر آیا جو تمہارے نفس کی خواہش کے مطابق نہ تھا تو تم نے تکبر کیا — پس ایک گروہ کو تم نے جھٹلایا اور ایک گروہ کو تم قتل کرتے ہو؟",
"""۱۔ اللہ نے حضرت موسیٰ علیہ السلام کو تورات دی پھر اس کے بعد مسلسل انبیاء مبعوث ہوتے رہے — ہر دور میں ہدایت کا سلسلہ جاری رہا۔
۲۔ ’’آتَيْنَا عِيسَى ابْنَ مَرْيَمَ الْبَيِّنَاتِ‘‘ — عیسیٰ ابن مریم کو واضح نشانیاں دیں (معجزات: بیماریوں سے شفا، مردوں کو زندہ کرنا وغیرہ)۔
۳۔ ’’وَأَيَّدْنَاهُ بِرُوحِ الْقُدُسِ‘‘ — اور انہیں روح القدس (جبرئیل علیہ السلام) سے مضبوط کیا — یعنی وحی اور الہام کے ذریعے۔
۴۔ ’’أَفَكُلَّمَا جَاءَكُمْ رَسُولٌ بِمَا لَا تَهْوَىٰ أَنفُسُكُمُ اسْتَكْبَرْتُمْ‘‘ — کیا جب کبھی تمہارے پاس کوئی پیغمبر وہ لے کر آیا جو تمہارے نفس کی خواہش کے مطابق نہ تھا تو تم نے تکبر کیا — یعنی بار بار نبی کو جھٹلانا ان کی عادت تھی۔
۵۔ ’’فَفَرِيقًا كَذَّبْتُمْ وَفَرِيقًا تَقْتُلُونَ‘‘ — پس ایک گروہ کو تم نے جھٹلایا اور ایک گروہ کو تم قتل کرتے ہو — زکریا اور یحییٰ علیہم السلام جیسے انبیاء کے قتل جیسے واقعات کی طرف اشارہ۔
۶۔ عملی سبق: جو نبی کی تعلیم نفس کی خواہش کے خلاف ہو تو اسے رد کرنے کے بجائے نفس کو درست کرو — ورنہ یہی بغاوت کی شروعات ہے۔"""
),
95: (
"اور انہوں نے کہا: ہمارے دل (علم سے) بھرے ہوئے ہیں — بلکہ اللہ نے ان کے کفر کی وجہ سے ان پر لعنت کی — تو وہ بہت کم ایمان لاتے ہیں۔",
"""۱۔ بنی اسرائیل غرور کر کے دعویٰ کرتے تھے: ’’قُلُوبُنَا غُلْفٌ‘‘ — ہمارے دل بھرے ہوئے ہیں (علم نبوت سے) — یعنی انہیں مزید کچھ معلوم کرنے کی ضرورت نہیں۔
۲۔ ’’بَل لَّعَنَهُمُ اللّٰہُ بِكُفْرِهِمْ‘‘ — بلکہ اللہ نے ان کے کفر کی وجہ سے ان پر لعنت کی — یعنی یہ غرور دراصل حق کے انکار کا نتیجہ ہے۔
۳۔ ’’فَقَلِيلًا مَّا يُؤْمِنُونَ‘‘ — تو وہ بہت کم ایمان لاتے ہیں — یعنی ان کا ایمان محض دعویٰ ہے، عمل میں بہت کم — یا وہ تھوڑے سے لوگ ہی ایمان لاتے ہیں۔
۴۔ غرورِ علم سب سے خطرناک بیماری ہے — جب دل بھرے ہونے کا دعویٰ ہو تو نئی بات سمجھنا مشکل ہو جاتا ہے۔
۵۔ عملی سبق: دل کو کبھی ’’بھر چکا‘‘ نہ سمجھیں؛ علم کی کوئی حد نہیں — ہمیشہ سیکھنے والا رہیں۔"""
),
96: (
"اور جب ان کے پاس اللہ کی طرف سے ایک کتاب آئی جو تصدیق کرتی ہے اس کی جو ان کے پاس ہے — حالانکہ وہ اس سے پہلے کافروں کے خلاف مدد مانگتے تھے (فتوحات کے لیے) — تو جب وہ چیز آئی جسے وہ پہچانتے تھے تو انہوں نے اس کا انکار کر دیا — پس اللہ کی لعنت کافروں پر ہے۔",
"""۱۔ اہلِ مدینہ (یہود) کے ہاں وہ قرآن، جس کی انہیں انتظار تھا، آ جاتا ہے — تصدیق بھی وہی ہے جو ان کی تورات میں تھی، پھر بھی حق پہچانتے ہوئے کفر کرتے ہیں۔
۲۔ ’’وَكَانُوا مِن قَبْلُ يَسْتَفْتِحُونَ عَلَى الَّذِينَ كَفَرُوا‘‘ — اور وہ اس سے پہلے کافروں کے خلاف قرآن کی مدد مانگتے تھے — یعنی مشرکینِ عرب کے خلاف مسلمانوں کی فتح کی دعا کرتے اور کہتے کہ نبی آخری ظاہر ہوگا۔
۳۔ ’’فَلَمَّا جَاءَهُم مَّا عَرَفُوا كَفَرُوا بِهِ‘‘ — پھر جب وہ چیز آئی جسے وہ پہچانتے تھے تو انہوں نے اس کا انکار کر دیا — یعنی تعصب اور ذاتی مفاد نے پہچان کے باوجود کفر کو اختیار کرا دیا۔
۴۔ ’’فَلَعْنَةُ اللّٰہِ عَلَى الْكَافِرِينَ‘‘ — پس اللہ کی لعنت کافروں پر ہے۔
۵۔ یہ واقعہ اس بات کی واضح دلیل ہے کہ انکار علم کی قلت سے نہیں بلکہ غرض پرستی سے ہوتا تھا۔
۶۔ عملی سبق: حق کی نشانی دکھائی دے تو فوراً قبول کر لیں — جانتے ہوئے انکار کرنے سے سنگین تر کوئی گناہ نہیں۔"""
),
97: (
"بہت بری ہے وہ چیز جس کے بدلے انہوں نے اپنی جانیں خریدیں — کہ وہ اللہ کے نازل کردہ (قرآن) کا انکار کریں — بغاوت میں اس لیے کہ اللہ اپنے فضل میں سے جسے چاہے اپنے بندوں میں سے نازل کرتا ہے — پس وہ غضب پر غضب لے کر آئے — اور کافروں کے لیے ذلیل کرنے والا عذاب ہے۔",
"""۱۔ بنی اسرائیل کا انکار غرض پرستی اور حسد پر قائم تھا — انہوں نے اپنی جانیں، یعنی اپنی فلاح، ایسے گناہ کے بدلے خریدیں۔
۲۔ ’’أَن يَكْفُرُوا بِمَا أَنزَلَ اللّٰہُ بَغْيًا‘‘ — کہ وہ اللہ کے نازل کردہ (قرآن) کا انکار کریں اپنی سرکشی سے — یعنی غرور اور ستم ظریفی کے باعث۔
۳۔ ’’أَن يُنَزِّلَ اللّٰہُ مِن فَضْلِهِ عَلَىٰ مَن يَشَاءُ مِنْ عِبَادِهِ‘‘ — اللہ اپنے فضل میں سے جسے چاہے اپنے بندوں میں نازل کرتا ہے — یعنی نبوت اللہ کا انتخاب ہے؛ بنی اسرائیل نے نبی ﷺ کو اپنی قوم سے نہ ہونے کے سبب حسد کا نشانہ بنایا۔
۴۔ ’’فَبَاءُوا بِغَضَبٍ عَلَىٰ غَضَبٍ‘‘ — پس وہ غضب پر غضب لے کر آئے — یعنی پچھلے گناہوں پر مزید اللہ کی ناراضی۔
۵۔ ’’وَلِلْكَافِرِينَ عَذَابٌ مُّهِينٌ‘‘ — اور کافروں کے لیے ذلیل کرنے والا عذاب ہے — یعنی سخت اور توہین آمیز سزا۔
۶۔ عملی سبق: حسد اور غرض پسندی کو چھوڑیں؛ اللہ کے فیاض فضل کو سر تسلیم خم کریں — انکار کا انجام رسوائی ہے۔"""
),
}
